from pathlib import Path
p = Path(r\"C:\\Users\\hzq00\\Documents\\Codex\\2026-08-29\\hy4-ai-ai-ai-ai-01a02ee0\\work\\sidebar_fix\")
needles = (\"breathe\", \"ToolTip\", \"DockBarToolTip\", \"hn_multiwindow_bar\", \"hotarea\", \"hot_area\", \"HotArea\")
files = list(p.glob(\"*\")) + list((p/\"reports\").glob(\"*\"))
for f in files:
    if f.is_dir():
        continue
    if f.suffix.lower() not in {\".txt\", \".py\", \".md\", \".json\", \".xml\"}:
        continue
    try:
        text = f.read_text(encoding=\"utf-8\", errors=\"ignore\")
    except Exception:
        continue
    hits = []
    for i, line in enumerate(text.splitlines(), 1):
        low = line.lower()
        if any(n.lower() in line or n.lower() in low for n in needles):
            hits.append((i, line[:240]))
            if len(hits) >= 40:
                break
    if hits:
        print(f\"\\n===== {f} ({len(hits)} shown) =====\")
        for i, line in hits:
            print(f\"{i}: {line}\")
'@ | python -"

